void Input_Back_List()
{
    if (int(now) != back_lists[0])
    {
        for (int i = 2; i >= 0; i--)
        {
            back_lists[i+1] = back_lists[i];
        }
        back_lists[0] = int(now);
    }
}

void Back()
{
    if ( digitalRead(BACK_BUTTON) == LOW && (millis() - LastTouched) > 300 )
    {
        LastTouched = millis();
        if ( back_lists[0] == int(Status::Controller) || back_lists[0] == int(Status::Menu) )
        {
            switch ( now )
            {
                case Status::Controller:
                    LeftRight = int(Menu_layout::Sensor);
                    break;

                case Status::Speed:
                    LeftRight = int(Menu_layout::Speed);
                    break;

                case Status::Kicker:
                    LeftRight = int(Menu_layout::Kicker);
                    break;

                case Status::Image:
                    LeftRight = int(Menu_layout::Image);
                    break;

                case Status::Gyro:
                    LeftRight = int(Sensor_layout::Gyro);
                    break;

                case Status::IR:
                    LeftRight = int(Sensor_layout::IR);
                    break;

                case Status::Line:
                    LeftRight = int(Sensor_layout::Line);
                    break;

                case Status::UltraSonic:
                    LeftRight = int(Sensor_layout::UltraSonic);
                    break;
            }
        }
        if (int(now) != back_lists[0])
        {
            now = Status(back_lists[0]);
            for (int i = 0; i < 3; i++)
            {
                back_lists[i] = back_lists[i+1];
            }
        }
        //return true;
    }
    else
    {
        //return false;
    }
}

bool Enter(){
    if ( digitalRead(ENTER_BUTTON) == LOW && (millis() - LastTouched) > 300 )
    {
        LastTouched = millis();
        Input_Back_List();
        return true;
    }
    else{
        return false;
    }
    
}

